@keyframes ssx-prehistoric-tail{0%, 100% { transform: rotate(-1.8deg); } 50% { transform: rotate(1.8deg); }}@keyframes ssx-prehistoric-graze{0%, 45%, 100% { transform: rotate(0deg); } 55%, 80% { transform: rotate(5deg); }}@keyframes ssx-prehistoric-wing{0%, 100% { transform: rotate(-10deg); } 50% { transform: rotate(10deg); }}@keyframes ssx-prehistoric-wing-far{0%, 100% { transform: rotate(10deg); } 50% { transform: rotate(-10deg); }}@keyframes ssx-prehistoric-glide{0%, 100% { transform: rotate(-2.5deg); } 50% { transform: rotate(2.5deg); }}@keyframes ssx-prehistoric-glide-far{0%, 100% { transform: rotate(2.5deg); } 50% { transform: rotate(-2.5deg); }}.ss-stage[data-scene="urzeit"] .ss-creature .part-tail{animation: ssx-prehistoric-tail 6s ease-in-out infinite;}.ss-stage[data-scene="urzeit"] .ss-creature .part-head{animation: ssx-prehistoric-graze 11s ease-in-out infinite;}.ss-stage[data-scene="urzeit"] .ss-creature .part-wings{animation: ssx-prehistoric-wing 1400ms ease-in-out infinite;}.ss-stage[data-scene="urzeit"] .ss-creature .part-wings-far{animation-name: ssx-prehistoric-wing-far;}.ss-stage[data-scene="urzeit"] .ss-creature .part-wings-slow{animation: ssx-prehistoric-glide 8s ease-in-out infinite;}.ss-stage[data-scene="urzeit"]
  .ss-creature
  .part-wings-slow.part-wings-far{animation-name: ssx-prehistoric-glide-far;}@keyframes ssx-prehistoric-fern{0%, 100% { transform: rotate(-2deg); } 50% { transform: rotate(2deg); }}@keyframes ssx-prehistoric-mist{from { transform: translateX(-100%); } to { transform: translateX(100cqw); }}@keyframes ssx-prehistoric-glint{0%, 100% { opacity: 0.15; transform: translateX(0); } 50% { opacity: 0.6; transform: translateX(calc(0.8 * var(--wu))); }}@keyframes ssx-prehistoric-herd{from { transform: translateX(calc(-3 * var(--wu))); } to { transform: translateX(calc(3 * var(--wu))); }}@keyframes ssx-prehistoric-sky-drift{from { transform: translateX(min(-20cqw, -100%)); } to { transform: translateX(110cqw); }}.ss-stage[data-scene="urzeit"] .ssx-far-flyers > svg,.ss-stage[data-scene="urzeit"] .ssx-far-herd > svg,.ss-stage[data-scene="urzeit"] .ssx-glint > svg{display: block; width: 100%; height: auto;}.ss-stage[data-scene="urzeit"] .ssx-fern > svg{display: block; height: 100%; width: auto;}.ss-stage[data-scene="urzeit"] .ssx-fern{transform-origin: bottom center; animation: ssx-prehistoric-fern ease-in-out infinite alternate;}.ss-stage[data-scene="urzeit"] .ssx-mist{left: 0; border-radius: 50%; background: radial-gradient( closest-side, rgb(240 238 226 / 0.9), rgb(240 238 226 / 0.45) 55%, rgb(240 238 226 / 0) ); animation: ssx-prehistoric-mist linear infinite;}.ss-stage[data-scene="urzeit"] .ssx-glint{animation: ssx-prehistoric-glint ease-in-out infinite;}.ss-stage[data-scene="urzeit"] .ssx-far-herd{opacity: 0.85; animation: ssx-prehistoric-herd 180s ease-in-out infinite alternate;}.ss-stage[data-scene="urzeit"] .ssx-far-flyers{left: 0; opacity: 0.8; animation: ssx-prehistoric-sky-drift linear infinite;}.ss-stage[data-scene="urzeit"]{background: #7a7652;}.ss-stage[data-scene="urzeit"][data-murky="true"]{filter: saturate(0.6) brightness(0.9) blur(1px);}.ss-stage[data-scene="urzeit"] .ss-veil{background: linear-gradient( to top, #dcdccd 0%, #dcdccd 35%, rgb(220 220 205 / 0.55) 100% );}.ss-stage[data-scene="urzeit"][data-murky="true"] .ss-veil{opacity: 0.4;}.ss-stage[data-scene="urzeit"][data-modus="weg"][data-murky="true"]{filter: saturate(0.85) brightness(0.96);}@media (prefers-reduced-motion: reduce){.ss-stage[data-scene="urzeit"] .ss-creature .part-tail,.ss-stage[data-scene="urzeit"] .ss-creature .part-head,.ss-stage[data-scene="urzeit"] .ss-creature .part-wings,.ss-stage[data-scene="urzeit"] .ssx-fern,.ss-stage[data-scene="urzeit"] .ssx-mist,.ss-stage[data-scene="urzeit"] .ssx-glint,.ss-stage[data-scene="urzeit"] .ssx-far-herd,.ss-stage[data-scene="urzeit"] .ssx-far-flyers{animation: none;}}
